-- Update library_playbooks with richer content_json including why, purpose, and detailed tasks
UPDATE library_playbooks SET content_json = '{"purpose":"Navigate your first 90 days at a new job with confidence and intention. Build relationships, prove value, and set the trajectory for your career.","why":"The first 90 days define how colleagues perceive you and set the foundation for years of growth. Getting this right compounds.","tasks":[{"title":"Schedule 1:1 with your manager","description":"Set expectations, understand priorities, and establish how you will be evaluated.","effort_minutes":30},{"title":"Map the org chart and key stakeholders","description":"Identify who influences decisions, who you need to impress, and who can mentor you.","effort_minutes":45},{"title":"Document your 30-60-90 day goals","description":"Write concrete deliverables for each phase so you have clarity and your manager has visibility.","effort_minutes":60},{"title":"Set up a daily learning block","description":"Block 30 minutes each morning for reading docs, understanding systems, and absorbing context.","effort_minutes":15},{"title":"Identify one quick win to deliver in week 1","description":"Find a small, visible improvement you can ship fast to build credibility.","effort_minutes":30},{"title":"Build a relationship map — coffee with 3 colleagues","description":"Schedule informal chats with people across teams to build trust and learn the culture.","effort_minutes":45}]}'::jsonb WHERE id = '6336f932-1fc8-4640-aab7-3f5651671c6a';

UPDATE library_playbooks SET content_json = '{"purpose":"Design a morning routine that creates momentum before the world demands your attention. This is your daily reset protocol.","why":"How you start the day defines your energy, focus, and emotional baseline. A structured morning compounds into a structured life.","tasks":[{"title":"Wake at a consistent time daily","description":"Set a non-negotiable wake time. Consistency trains your circadian rhythm for natural energy.","effort_minutes":5},{"title":"Hydrate before caffeine","description":"Drink a full glass of water before coffee. Rehydration after sleep is the simplest performance upgrade.","effort_minutes":2},{"title":"5-minute journal: gratitude + intention","description":"Write 3 things you are grateful for and your single most important intention for today.","effort_minutes":5},{"title":"10-minute movement or breathwork","description":"Stretch, walk, or do box breathing. Physical activation wakes up your nervous system.","effort_minutes":10},{"title":"Review your goals and calendar","description":"Spend 5 minutes scanning your priorities so you enter the day with clarity, not reactivity.","effort_minutes":5},{"title":"Protect the first 60 minutes from screens","description":"Delay email and social media. Your morning attention is your most valuable creative resource.","effort_minutes":0}]}'::jsonb WHERE id = '76d22b6d-e260-49b7-ad7d-ff4a65dc9f18';

UPDATE library_playbooks SET content_json = '{"purpose":"Examine your attachment patterns and communication defaults. Build awareness of how anxiety shows up in your closest relationships.","why":"Unexamined attachment patterns repeat themselves. Understanding your wiring is the first step toward secure, fulfilling connection.","tasks":[{"title":"Identify your attachment style","description":"Read about secure, anxious, avoidant, and disorganized styles. Reflect honestly on which resonates.","effort_minutes":30},{"title":"Map your triggers","description":"Write down 3 situations that trigger relationship anxiety. What happened? What story did you tell yourself?","effort_minutes":20},{"title":"Practice a repair conversation","description":"Draft what you would say to address a recent conflict using I-statements and vulnerability.","effort_minutes":15},{"title":"Set one boundary this week","description":"Identify something you need but have not asked for. Practice the ask, even if it feels uncomfortable.","effort_minutes":10},{"title":"Journal on your relationship origin story","description":"How did your earliest relationships shape what you expect from partners and friends?","effort_minutes":25}]}'::jsonb WHERE id = '7df81d32-7141-4f3d-98bc-c07b32e83605';

UPDATE library_playbooks SET content_json = '{"purpose":"Transform travel from consumption into an intentional experience. Plan trips that create memories, growth, and stories worth telling.","why":"Unplanned travel often defaults to tourist traps and exhaustion. Intentional planning turns every trip into a chapter of your life story.","tasks":[{"title":"Define the trip purpose","description":"Is this rest, adventure, cultural immersion, or reconnection? Name the intention before you book.","effort_minutes":15},{"title":"Create a flexible daily rhythm","description":"Plan 1-2 anchors per day (not an itinerary). Leave space for spontaneity and rest.","effort_minutes":30},{"title":"Research one local experience","description":"Find something authentic — a local market, neighborhood walk, or cultural event — not the top tourist result.","effort_minutes":20},{"title":"Pack intentionally","description":"Use a packing list. Aim for 50 percent fewer items than you think you need.","effort_minutes":15},{"title":"Set a daily reflection prompt","description":"Each evening, write one sentence about what surprised you today.","effort_minutes":5}]}'::jsonb WHERE id = 'a80efc6a-3a48-4cc4-97a8-66495262f602';

UPDATE library_playbooks SET content_json = '{"purpose":"Begin the intentional work of documenting what matters most — your values, wisdom, and the things you want remembered.","why":"Legacy is not about wealth. It is about what you pass forward — the lessons, stories, and principles that outlive you.","tasks":[{"title":"Write your personal values statement","description":"List your 5 core values. For each, write one sentence about why it matters to you.","effort_minutes":30},{"title":"Record a life lesson letter","description":"Write a letter to someone you love sharing one hard-won lesson from your experience.","effort_minutes":25},{"title":"Document a pivotal life moment","description":"Describe a turning point — what happened, what you learned, and how it shaped who you are.","effort_minutes":20},{"title":"Identify your contribution question","description":"Ask: What problem do I want to help solve? What would I do even without recognition?","effort_minutes":15},{"title":"Start a wisdom journal","description":"Create a recurring practice of capturing quotes, principles, and insights you want to preserve.","effort_minutes":10}]}'::jsonb WHERE id = '27da6e03-78cb-43fc-91da-c90545f26867';

UPDATE library_playbooks SET content_json = '{"purpose":"Execute a structured fat-loss phase while preserving lean mass. Prioritize sustainable habits over crash dieting.","why":"Crash diets sacrifice muscle and metabolism. A structured approach preserves what you built while getting lean sustainably.","tasks":[{"title":"Calculate your target caloric deficit","description":"Aim for 300-500 cal below maintenance. Use a TDEE calculator and track for 3 days to validate.","effort_minutes":20},{"title":"Set protein targets","description":"Aim for 1g per pound of body weight. Prioritize protein at every meal.","effort_minutes":10},{"title":"Plan 5 go-to meals","description":"Create a rotation of meals you enjoy that hit your macros. Prep components in advance.","effort_minutes":45},{"title":"Track daily for 7 days minimum","description":"Use an app to log food for one full week. Awareness alone changes behavior.","effort_minutes":10},{"title":"Schedule 3 resistance training sessions","description":"Maintain training volume to signal your body to preserve muscle during the deficit.","effort_minutes":15},{"title":"Set weekly weigh-in and photo check","description":"Track progress weekly, same conditions. Do not obsess over daily fluctuations.","effort_minutes":5}]}'::jsonb WHERE id = '6f98227a-f465-44c9-ae97-1af4665b16d3';

INSERT INTO library_playbooks (title, description, phase, category, published, content_json) VALUES
('Focus Reset Protocol', 'Reclaim your attention after a period of distraction, overwhelm, or digital noise.', 'builder', 'mindset', true, '{"purpose":"Break the cycle of scattered attention. This protocol helps you regain deep focus through environment design, digital boundaries, and intentional single-tasking.","why":"Attention is your most valuable resource. When it fragments, everything suffers — work quality, relationships, and self-trust.","tasks":[{"title":"Audit your screen time for 3 days","description":"Check your screen time report. Identify the top 3 time sinks that do not serve you.","effort_minutes":10},{"title":"Create a distraction-free work block","description":"Block 90 minutes daily. Phone on airplane mode. Close all tabs except your task.","effort_minutes":5},{"title":"Unsubscribe from 10 email lists","description":"Reduce inbox noise. Every unnecessary email is a micro-interruption.","effort_minutes":15},{"title":"Set phone-free zones","description":"Designate bedroom and dining table as no-phone areas. Charge outside your bedroom.","effort_minutes":5},{"title":"Practice single-tasking for one day","description":"Do one thing at a time for a full day. Notice the resistance — that is the reset working.","effort_minutes":0}]}'::jsonb),
('Weekly Planning Ritual', 'A structured system to plan your week with clarity, balance, and strategic intent.', 'builder', 'productivity', true, '{"purpose":"Replace reactive weeks with intentional ones. This ritual ensures your time aligns with your priorities, not just your inbox.","why":"Without a weekly plan, urgent tasks crowd out important ones. Planning is how you defend your goals from the noise of daily life.","tasks":[{"title":"Review last week: wins and gaps","description":"Spend 10 minutes listing what went well and what slipped. No judgment — just data.","effort_minutes":10},{"title":"Identify your 3 priorities for the week","description":"What are the 3 outcomes that would make this week successful? Write them down.","effort_minutes":10},{"title":"Time-block your calendar","description":"Assign your priorities to specific blocks. Protect deep work time from meetings.","effort_minutes":15},{"title":"Batch small tasks","description":"Group emails, errands, and admin into 1-2 batches. Stop context-switching.","effort_minutes":10},{"title":"Schedule rest and recovery","description":"Block at least one evening with no obligations. Recovery is productive.","effort_minutes":5}]}'::jsonb),
('Momentum Recovery After Drift', 'Get back on track after falling off your routines. No shame — just structured re-engagement.', 'builder', 'mindset', true, '{"purpose":"Everyone drifts. This playbook helps you return to your systems without the spiral of self-criticism. Start small. Build back momentum.","why":"The gap between who you are and who you want to be grows during drift. Closing it starts with one intentional day.","tasks":[{"title":"Acknowledge the drift without judgment","description":"Write one sentence: I drifted because ___. Now I am choosing to return.","effort_minutes":5},{"title":"Pick ONE habit to restart today","description":"Not all of them. Just one. The smallest one. Build the muscle of showing up again.","effort_minutes":5},{"title":"Set a 3-day challenge","description":"Commit to 3 consecutive days of your chosen habit. Three days breaks the inertia.","effort_minutes":5},{"title":"Remove one friction point","description":"What made it hard last time? Remove that barrier. Make the right thing easier.","effort_minutes":10},{"title":"Tell someone you are starting again","description":"Accountability is not weakness. Share your intention with one person who supports you.","effort_minutes":5}]}'::jsonb),
('Financial Order Reset', 'Bring clarity and control to your finances in one focused session.', 'builder', 'money', true, '{"purpose":"Stop avoiding your finances. This playbook gives you a clear snapshot of where you stand and what to do next.","why":"Financial anxiety grows in the dark. Clarity — even uncomfortable clarity — is the first step to financial confidence.","tasks":[{"title":"List all accounts and balances","description":"Every bank account, credit card, loan, and investment. Write them all down in one place.","effort_minutes":20},{"title":"Calculate your monthly burn rate","description":"Total your recurring expenses. Know exactly what it costs to be you each month.","effort_minutes":15},{"title":"Identify one expense to eliminate","description":"Find one subscription, service, or habit that no longer serves you. Cancel it today.","effort_minutes":10},{"title":"Set up automatic savings","description":"Even $25/month matters. Automate it so saving happens without willpower.","effort_minutes":10},{"title":"Define your 3-month financial goal","description":"Emergency fund? Debt payoff? A specific purchase? Name it and put a number on it.","effort_minutes":10}]}'::jsonb),
('Journal Clarity Sequence', 'Use structured journaling to process emotions, gain clarity, and make better decisions.', 'family_home', 'mindset', true, '{"purpose":"Move from mental fog to clarity through guided writing. These prompts help you process what is happening and choose your next move intentionally.","why":"Your thoughts become clearer when they leave your head. Writing is thinking made visible — and visible thinking is actionable thinking.","tasks":[{"title":"Brain dump: write everything on your mind","description":"Set a 10-minute timer. Write without filtering. Get everything out of your head onto paper.","effort_minutes":10},{"title":"Identify the real question","description":"From your brain dump, find the one question underneath everything. What are you really trying to figure out?","effort_minutes":10},{"title":"Write from your future self","description":"Imagine you solved this. What did future-you do? Write advice from that perspective.","effort_minutes":15},{"title":"Name your emotions","description":"List what you are feeling. Naming emotions reduces their power and increases your clarity.","effort_minutes":5},{"title":"Choose one action","description":"Based on everything you wrote, identify the single next step. Write it as a task.","effort_minutes":5}]}'::jsonb),
('Personal Reset After a Hard Week', 'Recover your energy and perspective after a challenging or draining period.', 'family_home', 'health', true, '{"purpose":"When life hits hard, you need a structured recovery — not willpower. This playbook guides you through physical, emotional, and mental restoration.","why":"Pushing through without recovery leads to burnout. Strategic rest is not lazy — it is how resilient people sustain themselves.","tasks":[{"title":"Cancel one non-essential obligation","description":"Give yourself permission to say no to something this week. Protect your recovery time.","effort_minutes":5},{"title":"Take a 20-minute walk without your phone","description":"Movement plus solitude is the fastest reset for your nervous system.","effort_minutes":20},{"title":"Sleep 8 hours tonight","description":"Set an alarm for bedtime, not just morning. Sleep debt compounds stress.","effort_minutes":5},{"title":"Write 3 things that went right this week","description":"Even in a hard week, something worked. Name it. Gratitude anchors perspective.","effort_minutes":5},{"title":"Reach out to one person who energizes you","description":"Send a text, make a call. Connection is medicine for isolation.","effort_minutes":10}]}'::jsonb);